"use client";

/**
 * NotificationCenter. An inbox of what happened: a bell key with the unread
 * count on it, opening a panel of notifications, newest first. Unread ones
 * carry a lit LED; opening one marks it read; "Mark all read" clears them.
 * It's where a toast goes after it has gone: a person who missed it finds it
 * here.
 *
 * The bell is a real button named with the count ("Notifications, 3
 * unread"); the panel is a Popover with a heading and a list of Items.
 */
import type { ReactNode } from "react";
import { HardwareButton } from "../hardware-button";
import { Popover } from "../popover";
import { CountBadge } from "../count-badge";
import { Item } from "../item";
import "./notification-center.css";

export interface Notification {
  id: string;
  title: string;
  body?: ReactNode;
  /** When, as you want it shown: "2m", "Mon". */
  time?: string;
  read?: boolean;
  /** Where opening it goes. */
  href?: string;
}

export interface NotificationCenterProps {
  notifications: Notification[];
  /** Called when one is opened. Mark it read here. */
  onOpen?: (id: string) => void;
  /** Called by "Mark all read". */
  onReadAll?: () => void;
  /** What an empty inbox says. Default "Nothing new." */
  emptyText?: ReactNode;
}

const Bell = () => (
  <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M4 11V7a4 4 0 0 1 8 0v4l1.2 1.5H2.8zM6.5 14h3" />
  </svg>
);

export function NotificationCenter({ notifications, onOpen, onReadAll, emptyText = "Nothing new." }: NotificationCenterProps) {
  const unread = notifications.filter((n) => !n.read).length;
  const name = unread ? `Notifications, ${unread} unread` : "Notifications";
  return (
    <span className="echo-notifications">
      <Popover
        side="bottom"
        align="end"
        title="Notifications"
        trigger={<HardwareButton iconOnly aria-label={name} icon={<Bell />} />}
      >
        <div className="echo-notifications__panel">
          <div className="echo-notifications__head">
            <span className="echo-notifications__count">{unread ? `${unread} unread` : "All read"}</span>
            {unread && onReadAll ? (
              <HardwareButton size="sm" variant="ghost" onClick={onReadAll}>
                Mark all read
              </HardwareButton>
            ) : null}
          </div>
          {notifications.length ? (
            <ul className="echo-notifications__list">
              {notifications.map((n) => (
                <Item
                  key={n.id}
                  as="li"
                  size="sm"
                  media={<span className="echo-notifications__led" data-unread={n.read ? undefined : ""} aria-hidden="true" />}
                  title={
                    <>
                      {n.title}
                      {n.read ? null : <span className="echo-notifications__sr"> (unread)</span>}
                    </>
                  }
                  description={n.body}
                  trailing={n.time}
                  {...(n.href ? { href: n.href } : {})}
                  onClick={() => onOpen?.(n.id)}
                />
              ))}
            </ul>
          ) : (
            <p className="echo-notifications__empty">{emptyText}</p>
          )}
        </div>
      </Popover>
      {unread ? (
        <span className="echo-notifications__badge" aria-hidden="true">
          <CountBadge count={unread} label="unread" />
        </span>
      ) : null}
    </span>
  );
}

/**
 * NotificationCenter. The bell cap with its count pinned to the corner; the
 * panel a short list of Items, each with an LED lit while unread.
 */
.echo-notifications {
  position: relative;
  display: inline-flex;
}
/* Over the bell's top corner: above it, never past its side (that would push
   a narrow row open). */
.echo-notifications__badge {
  position: absolute;
  top: calc(-1 * var(--echo-space-4));
  inset-inline-end: 0;
  pointer-events: none;
}
.echo-notifications__panel {
  display: grid;
  gap: var(--echo-space-4);
  width: min(22rem, calc(100vw - 2rem));
}
.echo-notifications__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--echo-space-6);
}
.echo-notifications__count {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}
.echo-notifications__list {
  max-height: min(24rem, 60vh);
  margin: 0;
  padding: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  list-style: none;
}
.echo-notifications__led {
  display: block;
  width: 8px;
  height: 8px;
  border-radius: var(--echo-radius-full);
  background: color-mix(in oklab, var(--echo-cap) 70%, var(--echo-text-dim));
}
.echo-notifications__led[data-unread] {
  background: linear-gradient(180deg, var(--echo-primary-cap-top), var(--echo-primary-cap-base));
  box-shadow: 0 0 6px color-mix(in oklch, var(--echo-accent-glow) 60%, transparent);
}
.echo-notifications__sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.echo-notifications__empty {
  margin: 0;
  padding: var(--echo-space-8) 0;
  text-align: center;
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}
@media (forced-colors: active) {
  .echo-notifications__led[data-unread] {
    background: Highlight;
  }
}
